def check(obj):
    call = obj
    while isinstance(call, functools.partial):
        call = call.func
    if inspect.isroutine(call):
        return asyncio.iscoroutinefunction(call)
    if inspect.isclass(call):
        return False
    dunder_call = getattr(call, '__call__', None)
    return asyncio.iscoroutinefunction(dunder_call)

print(f'async_fn: {check(async_fn)}')
print(f'partial(async_fn): {check(functools.partial(async_fn))}')
print(f'partial(partial(async_fn)): {check(functools.partial(functools.partial(async_fn)))}')
print(f'sync_fn: {check(sync_fn)}')
print(f'partial(sync_fn): {check(functools.partial(sync_fn))}')
print(f'AsyncCall(): {check(AsyncCall())}')
print(f'partial(AsyncCall()): {check(functools.partial(AsyncCall()))}')
print(f'SyncCall(): {check(SyncCall())}')
print(f'partial(SyncCall()): {check(functools.partial(SyncCall()))}')
